:root {
  /* Colors */
  --color-jet-canvas: #08090a;
  --color-carbon-panel: #0f1011;
  --color-graphite-tile: #161718;
  --color-frosted-glass: #ffffff05;
  --color-slate-muted: #62666d;
  --color-steel-caption: #8a8f98;
  --color-mist-text: #d0d6e0;
  --color-fog-label: #e2e4e7;
  --color-paper-ink: #f7f8f8;
  --color-ash-hairline: #ffffff14;
  --color-iron-rule: #23252a;
  --color-dove-fill: #e5e5e6;
  --color-iris-signal: #5e6ad2;

  /* Typography — Font Families */
  --font-inter-variable: "Inter Variable", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-berkeley-mono: "Berkeley Mono", "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 10px;
  --leading-small: 1.4;
  --tracking-small: -0.15px;
  --text-caption: 12px;
  --leading-caption: 1.4;
  --tracking-caption: 0px;
  --text-body-sm: 13px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: -0.13px;
  --text-body: 15px;
  --leading-body: 1.6;
  --tracking-body: -0.165px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.6;
  --tracking-body-lg: -0.165px;
  --text-subheading: 20px;
  --leading-subheading: 1.33;
  --tracking-subheading: -0.24px;
  --text-heading-sm: 24px;
  --leading-heading-sm: 1.33;
  --tracking-heading-sm: -0.288px;
  --text-heading: 48px;
  --leading-heading: 1;
  --tracking-heading: -1.056px;
  --text-display: 64px;
  --leading-display: 1;
  --tracking-display: -1.408px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 510;
  --font-weight-semibold: 590;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-128: 128px;

  /* Layout */
  --layout-max-width: 1250px;
  --layout-section-gap: 128px;
  --layout-card-padding: 16px;
  --layout-element-gap: 8px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 9px;
  --radius-2xl: 12px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-nav: 9999px;
  --radius-tags: 9999px;
  --radius-cards: 9px;
  --radius-sections: 12px;
  --radius-innerTiles: 8px;
  --radius-inputs: 8px;
  --radius-smallCards: 6px;
  --radius-images: 6px;
  --radius-badges: 4px;
  --radius-smallElements: 4px;
  --radius-avatars: 50%;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0.2) 0px 0px 0px 1px;
  --shadow-subtle-2: rgba(255, 255, 255, 0.05) 0px 0px 0px 1px inset;
  --shadow-sm: rgba(255, 255, 255, 0.08) 0px 0px 0px 0.5px inset;
  --shadow-md: rgba(0, 0, 0, 0) 0px 8px 2px 0px, rgba(0, 0, 0, 0.01) 0px 5px 2px 0px, rgba(0, 0, 0, 0.04) 0px 3px 2px 0px, rgba(0, 0, 0, 0.07) 0px 1px 1px 0px, rgba(0, 0, 0, 0.08) 0px 0px 1px 0px;
  --shadow-md-2: rgba(0, 0, 0, 0.2) 0px 0px 12px 0px inset;
  --shadow-lg: rgba(0, 0, 0, 0.25) 0px 2px 32px 0px;

  /* Surfaces */
  --surface-jet-canvas: #08090a;
  --surface-carbon-panel: #0f1011;
  --surface-graphite-tile: #161718;
  --surface-frosted-glass: #ffffff05;
  --surface-dove-fill: #e5e5e6;
}

